samples.raw_completion:
// FSM, priority arbiter: grants requests to the highest-numbered device
// that is requesting, in order of increasing device number.
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    // State register: our current state (and next state, a combinational
    // function of the current state and the input) is registered to the
    // clock domain, so as to allow the input to change immediately at the
    // same time as the state transition.
    reg [2:0] s, sn;
    always @(posedge clk) begin
        if (!resetn) s <= 3'b000;
        else s <= sn;
    end
    // State table: combinational function of the current state and the
    // input, that defines the next state.
    always @(*) begin
        case (s)
            3'b000: if (r[0]) sn = 3'b001; else if (r[1]) sn = 3'b010; else if (r[2]) sn = 3'b100; else sn = 3'b000;
            3'b001: if (r[0]) sn = 3'b001; else if (r[1]) sn = 3'b010; else if (r[2]) sn = 3'b100; else sn = 3'b000;
            3'b010: if (r[1]) sn = 3'b010; else if (r[0]) sn = 3'b001; else if (r[2]) sn = 3'b100; else sn = 3'b000;
            3'b100: if (r[2]) sn = 3'b100; else if (r[0]) sn = 3'b001; else if (r[1]) sn = 3'b010; else sn = 3'b000;
            default: sn = 3'b000;
        endcase
    end
    // Outputs, as a function of the current state: the grant to device 0, 1
    // and 2, in order of increasing device number.
    assign g[0] = (s == 3'b000) || (s == 3'b001) || (s == 3'b100);
    assign g[1] = (s == 3'b000) || (s == 3'b010) || (s == 3'b100);
    assign g[2] = (s == 3'b000) || (s == 3'b010) || (s == 3'b001);
endmodule

