module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [2:0] state;
  reg [2:0] next_state;
  wire [2:0] r_inv = ~r;
  wire [2:0] priority = r_inv & {3{1'b1}};
  reg [2:0] grant;
  always @(*) begin
    case (state)
      3'd0: next_state = (priority == 3'd1) ? 3'd1 :
                         (priority == 3'd2) ? 3'd2 :
                         (priority == 3'd4) ? 3'd3 : 3'd0;
      3'd1: next_state = (r[0] == 1'b1) ? 3'd1 : 3'd0;
      3'd2: next_state = (r[1] == 1'b1) ? 3'd2 : 3'd0;
      3'd3: next_state = (r[2] == 1'b1) ? 3'd3 : 3'd0;
    endcase
  end
  always @(posedge clk) begin
    if (~resetn) state <= 3'd0;
    else state <= next_state;
  end
  always @(*) begin
    grant = (state == 3'd1) ? 3'd1 :
            (state == 3'd2) ? 3'd2 :
            (state == 3'd3) ? 3'd3 : 3'd0;
    g = (state == 3'd1) ? {1'b1, 1'b0, 1'b0} :
        (state == 3'd2) ? {1'b0, 1'b1, 1'b0} :
        (state == 3'd3) ? {1'b0, 1'b0, 1'b1} : {1'b0, 1'b0, 1'b0};
  end
endmodule

