module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, nextstate;
    wire [2:0] g_comb;
    reg [2:0] g_reg;
    always @* begin
        case (state)
            2'd0: g_comb = 3'b001;
            2'd1: g_comb = 3'b010;
            2'd2: g_comb = 3'b100;
            2'd3: g_comb = 3'b001;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'd0;
            g_reg <= 3'b001;
        end else begin
            state <= nextstate;
            g_reg <= g_comb;
        end
    end
    always @* begin
        case (state)
            2'd0: nextstate = (r[0]) ? 2'd1 : (r[1]) ? 2'd2 : (r[2]) ? 2'd3 : 2'd0;
            2'd1: nextstate = (r[0]) ? 2'd1 : 2'd0;
            2'd2: nextstate = (r[1]) ? 2'd2 : 2'd0;
            2'd3: nextstate = (r[2]) ? 2'd3 : ((r[1]) ? 2'd2 : ((r[0]) ? 2'd1 : 2'd0));
        endcase
    end
    assign g = g_reg;
endmodule

