// One-hot state codes:
//   000: A
//   001: B
//   010: C
//   011: D
//   100: E
//   101: F
//   110: G
//   111: H
// The FSM itself is a prioritised arbiter, with the first device in the
// one-hot state code (from left to right, where 0 is the least
// significant bit) given a grant.
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [2:0] state, nextstate;
  reg [2:0] r_reg [0:2];
  wire [2:0] grant;
  reg [2:0] state2;
  always @(*) begin
    r_reg[0] = r[0];
    r_reg[1] = r[1];
    r_reg[2] = r[2];
    case (state)
      3'b000: nextstate = (~r[0] & ~r[1] & ~r[2]) ? 3'b000 :
                           (r[0]) ? 3'b001 :
                           (~r[0] & r[1]) ? 3'b010 : 3'b011;
      3'b001: nextstate = (~r[0]) ? 3'b001 : 3'b000;
      3'b010: nextstate = (~r[1]) ? 3'b010 : 3'b000;
      3'b011: nextstate = (~r[0] & ~r[1] & ~r[2]) ? 3'b011 :
                           (r[0]) ? 3'b100 :
                           (~r[0] & r[1]) ? 3'b101 : 3'b110;
      3'b100: nextstate = (~r[0]) ? 3'b100 : 3'b011;
      3'b101: nextstate = (~r[1]) ? 3'b101 : 3'b011;
      3'b110: nextstate = (~r[0] & ~r[1] & ~r[2]) ? 3'b110 :
                           (r[2]) ? 3'b111 :
                           (~r[0] & r[1]) ? 3'b001 : 3'b010;
      3'b111: nextstate = (~r[2]) ? 3'b111 : 3'b110;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 3'b000;
    else state <= nextstate;
  end
  assign grant = {1'b1,1'b1,1'b1} >> state[2:0];
  always @(*) g[0] = (state == 3'b000 || state == 3'b011) ? grant[0] : 1'b0;
  always @(*) g[1] = (state == 3'b000 || state == 3'b011) ? grant[1] : 1'b0;
  always @(*) g[2] = (state == 3'b000 || state == 3'b011 || state == 3'b110) ? grant[2] : 1'b0;
endmodule

