// One-hot state codes: state names are the same as the state codes.
// (The FSM itself is a state machine, so we don't need to explicitly
// name all the states.)
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [2:0] state, nextstate;
  always @(*) begin
    case (state)
      3'b000: nextstate = 3'b000;
      3'b000: nextstate = r[0] ? 3'b001 : (r[1] ? 3'b010 : (r[2] ? 3'b100 : 3'b000));
      3'b001: nextstate = r[0] ? 3'b001 : 3'b000;
      3'b010: nextstate = r[1] ? 3'b010 : 3'b000;
      3'b100: nextstate = r[2] ? 3'b100 : (r[1] ? 3'b010 : (r[0] ? 3'b001 : 3'b000));
      default: nextstate = 3'b000;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 3'b000;
    else state <= nextstate;
  end
  assign g[0] = (state == 3'b000) || (state == 3'b001) || (state == 3'b100);
  assign g[1] = (state == 3'b010);
  assign g[2] = (state == 3'b100);
endmodule

