// FSM as an arbiter, with priority over the requests, as described in the
// problem description.
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, next_state;
    wire [2:0] g0, g1, g2;
    reg [2:0] g_reg;
    wire [2:0] g_next;
    reg [2:0] r_reg;
    always @(*) begin
        case (state)
            2'b00: next_state = (r == 3'b000) ? 2'b00 :
                                (r[0])          ? 2'b01 : 2'b10;
            2'b01: next_state = (r[0])          ? 2'b01 : 2'b00;
            2'b10: next_state = (r[1])          ? 2'b10 : 2'b00;
            2'b11: next_state = (r == 3'b000) ? 2'b11 :
                                (r[0])          ? 2'b01 :
                                (r[1])          ? 2'b10 : 2'b00;
        endcase
    end
    always @(*) begin
        case (state)
            2'b00: g0 = 1; g1 = 0; g2 = 0;
            2'b01: g0 = 0; g1 = 1; g2 = 0;
            2'b10: g0 = 0; g1 = 0; g2 = 1;
            2'b11: g0 = 1; g1 = 1; g2 = 1;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            g_reg <= 3'b000;
            r_reg <= 3'b000;
        end else begin
            state <= next_state;
            g_reg <= g_next;
            r_reg <= r;
        end
    end
    assign g = g_reg;
    always @(*) g_next = {g2, g1, g0};
endmodule

