// The FSM, as a register-based state machine. Same function as the
// register-based state machine, but the state register is explicitly
// named "state" instead of "reg".
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [2:0] state, nextstate;
  always @(*) begin
    case (state)
      // Functionally the same as state 0.
      // Same as setting g[0]=1, g[1]=0, g[2]=0.
      // Same as setting g0=1, g1=0, g2=0.
      3'b000: nextstate = 3'b001;
      // Same as state 1.
      // Same as setting g[0]=0, g[1]=1, g[2]=0.
      // Same as setting g0=0, g1=1, g2=0.
      3'b001: nextstate = r[0] ? 3'b011 : 3'b000;
      // Same as state 2.
      // Same as setting g[0]=0, g[1]=0, g[2]=1.
      // Same as setting g0=0, g1=0, g2=1.
      3'b010: nextstate = r[0] ? 3'b010 : (r[1] ? 3'b011 : 3'b000);
      // Same as state 3.
      // Same as setting g[0]=1, g[1]=1, g[2]=0.
      // Same as setting g0=1, g1=1, g2=0.
      3'b011: nextstate = r[0] ? 3'b010 : (r[1] ? 3'b011 : 3'b100);
      // Same as state 4.
      // Same as setting g[0]=1, g[1]=0, g[2]=1.
      // Same as setting g0=1, g1=0, g2=1.
      3'b100: nextstate = r[2] ? 3'b111 : (r[0] ? 3'b010 : (r[1] ? 3'b011 : 3'b000));
      // Same as state 5.
      // Same as setting g[0]=0, g[1]=1, g[2]=1.
      // Same as setting g0=0, g1=1, g2=1.
      3'b101: nextstate = r[1] ? 3'b011 : (r[2] ? 3'b111 : (r[0] ? 3'b010 : 3'b000));
      // Same as state 6.
      // Same as setting g[0]=0, g[1]=0, g[2]=0.
      // Same as setting g0=0, g1=0, g2=0.
      default: nextstate = 3'b000;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 3'b000;
    else         state <= nextstate;
  end
  assign g = (1 << state[2:0]);
endmodule

