  always @(*) begin
    case (state)
      // Functionally the same as state 0.
      // Same as setting g[0]=1, g[1]=0, g[2]=0.
      // Same as setting g0=1, g1=0, g2=0.
      3'b000: nextstate = 3'b001;
      // Same as state 1.
      // Same as setting g[0]=0, g[1]=1, g[2]=0.
      // Same as setting g0=0, g1=1, g2=0.
      3'b001: nextstate = r[0] ? 3'b011 : 3'b000;
