      // Same as setting g0=1, g1=1, g2=0.
      3'b011: nextstate = r[0] ? 3'b010 : (r[1] ? 3'b011 : 3'b100);
      // Same as state 4.
      // Same as setting g[0]=1, g[1]=0, g[2]=1.
      // Same as setting g0=1, g1=0, g2=1.
      3'b100: nextstate = r[2] ? 3'b111 : (r[0] ? 3'b010 : (r[1] ? 3'b011 : 3'b000));
