      // Same as setting g[0]=0, g[1]=1, g[2]=1.
      // Same as setting g0=0, g1=1, g2=1.
      3'b101: nextstate = r[1] ? 3'b011 : (r[2] ? 3'b111 : (r[0] ? 3'b010 : 3'b000));
