      // Same as setting g[0]=0, g[1]=0, g[2]=0.
      // Same as setting g0=0, g1=0, g2=0.
      default: nextstate = 3'b000;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 3'b000;
    else         state <= nextstate;
  end
  assign g = (1 << state[2:0]);
