// One-hot state codes:
//   [0] -> A
//   [1] -> B
//   [2] -> C
//   [3] -> D
// Toggle the appropriate bit in the state register to go to a new state.
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, nextstate;
    always @(*) begin
        case (state)
            // state A
            3'b000: nextstate = (r == 3'b001) ? 3'b001 :
                                (r == 3'b010) ? 3'b011 :
                                (r == 3'b100) ? 3'b111 : 3'b000;
            // state B
            3'b001: nextstate = (r == 3'b001) ? 3'b001 :
                                (r == 3'b000) ? 3'b000 : 3'b010;
            // state C
            3'b011: nextstate = (r == 3'b010) ? 3'b011 :
                                (r == 3'b000) ? 3'b000 : 3'b000;
            // state D
            3'b111: nextstate = (r == 3'b100) ? 3'b111 :
                                (r == 3'b000) ? 3'b000 : 3'b010;
            default: nextstate = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if (~resetn) state <= 3'b000;
        else         state <= nextstate;
    end
    // describe the outputs in an always block
    always @(*) begin
        g = (state == 3'b000) ? 3'b001 :
            (state == 3'b001) ? 3'b001 :
            (state == 3'b011) ? 3'b010 :
            (state == 3'b111) ? 3'b100 : 3'b000;
    end
endmodule

