// FSM as an arbiter: the FSM decides which device gets a grant to use the
// resource, and that device continues to get the grant as long as its
// request, _r[i]_, is set. The FSM stays in state _A_ as long as there
// are no requests.
module TopModule(clk, resetn, r, g);
  input clk, resetn;
  input [2:0] r;
  output [2:0] g;
  reg [1:0] state, nextstate;
  wire [2:0] r0g, r1g, r2g;
  reg [2:0] greg;
  reg [2:0] r0, r1, r2;
  always @(*) begin
    case (state)
      2'b00: nextstate = 2'b00;
      2'b01: nextstate = r[0] ? 2'b01 : 2'b00;
      2'b10: nextstate = r[0] ? 2'b01 : (r[1] ? 2'b10 : 2'b00);
      2'b11: nextstate = r[0] ? 2'b01 : (r[1] ? 2'b10 : (r[2] ? 2'b11 : 2'b00));
    endcase
  end
  always @(*) begin
    r0g = (state == 2'b00 | state == 2'b01) & r[0];
    r1g = (state == 2'b01 | state == 2'b10) & r[1];
    r2g = (state == 2'b10 | state == 2'b11) & r[2];
    greg = r0g ? 3'b001 : (r1g ? 3'b010 : (r2g ? 3'b100 : 3'b000));
  end
  always @(posedge clk) begin
    if (!resetn) begin
      state <= 2'b00; r0 <= 1'b0; r1 <= 1'b0; r2 <= 1'b0;
    end else begin
      state <= nextstate; r0 <= r[0]; r1 <= r[1]; r2 <= r[2];
    end
  end
  assign g = greg;
endmodule

