// FSM as an arbiter, with priority-based grant to the highest-numbered
// requesting device.
module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [1:0] state, nextstate;
  wire [2:0] grant;
  reg [2:0] rd;
  always @(*) begin
    case (state)
      2'd0: grant = r[0] ? 3'd1 : (r[1] ? 3'd2 : (r[2] ? 3'd3 : 3'd0));
      2'd1: grant = r[0] ? 3'd1 : 3'd0;
      2'd2: grant = r[1] ? 3'd2 : 3'd0;
      2'd3: grant = r[2] ? 3'd3 : 3'd0;
      default: grant = 3'd0;
    endcase
  end
  always @(*) begin
    case (state)
      2'd0: nextstate = r[0] | r[1] | r[2] ? 2'd1 : 2'd0;
      2'd1: nextstate = r[0] ? 2'd1 : (r[1] | r[2] ? 2'd2 : 2'd0);
      2'd2: nextstate = r[1] ? 2'd2 : (r[2] ? 2'd3 : 2'd0);
      2'd3: nextstate = r[2] ? 2'd3 : 2'd0;
      default: nextstate = 2'd0;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 2'd0;
    else state <= nextstate;
  end
  always @(posedge clk) rd <= r;
  assign g = (state == 2'd0 && !rd[0] && !rd[1] && !rd[2]) ? 3'd1 :
             (state == 2'd1 && !rd[0] && !rd[1] && !rd[2]) ? 3'd2 :
             (state == 2'd2 && !rd[0] && !rd[1] && !rd[2]) ? 3'd4 : 3'd0;
endmodule

